const items = $input.all();
const formData = items[0].json;

// ── number generation ──────────────────────────────────────────────────────
const existingCount = $('Leer Facturas').all().length;
const year = new Date().getFullYear();
const nextNum = String(existingCount + 1).padStart(3, '0');
const numFactura = `FAC-${year}-${nextNum}`;

// ── parse line items from textarea (one per line: qty|description|unit_price) ──
const rawItems = (formData['Lineas de Factura'] || '').split('\n').map(l => l.trim()).filter(Boolean);
const lineItems = rawItems.map(line => {
  const parts = line.split('|').map(p => p.trim());
  const qty = parseFloat(parts[0]) || 1;
  const desc = parts[1] || line;
  const unitPrice = parseFloat(parts[2]) || 0;
  return {qty, desc, unitPrice, total: qty * unitPrice};
});

const iva = parseFloat(formData['IVA Porcentaje'] || 21);
const base = lineItems.reduce((s, i) => s + i.total, 0);
const ivaAmount = base * (iva / 100);
const total = base + ivaAmount;

const fmt = v => parseFloat(v).toLocaleString('es-ES', {minimumFractionDigits: 2, maximumFractionDigits: 2}) + ' €';
const hoy = new Date();
const fechaHoy = hoy.toLocaleDateString('es-ES', {day: 'numeric', month: 'long', year: 'numeric'});

// ── empresa (PERSONALIZA ESTOS DATOS) ─────────────────────────────────────
const empresa = {
  nombre:    "TU EMPRESA S.L.",
  nif:       "B12345678",
  direccion: "Calle Ejemplo, 123",
  ciudad:    "28001 Madrid",
  email:     "info@tuempresa.com",
  telefono:  "+34 600 000 000",
  banco:     "ES00 0000 0000 0000 0000 0000",
};

const lineRows = lineItems.map(i => `
  <tr>
    <td style="text-align:center">${i.qty}</td>
    <td>${i.desc}</td>
    <td style="text-align:right">${fmt(i.unitPrice)}</td>
    <td style="text-align:right;font-weight:600">${fmt(i.total)}</td>
  </tr>`).join('');

const html = `<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Factura ${numFactura}</title>
<style>
  *{margin:0;padding:0;box-sizing:border-box}
  body{font-family:system-ui,Arial,sans-serif;font-size:11pt;color:#1a1a1a;background:#fff}
  .page{max-width:800px;margin:0 auto;padding:50px 60px}
  .header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #059669;padding-bottom:20px;margin-bottom:30px}
  .co-name{font-size:20pt;font-weight:700;color:#059669}
  .co-info{font-size:9pt;color:#64748b;margin-top:6px}
  .doc-title h1{font-size:18pt;color:#1a1a1a;text-align:right}
  .doc-title p{font-size:10pt;color:#64748b;text-align:right;margin-top:4px}
  .parties{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:24px 0;padding:20px;background:#f0fdf4;border-radius:8px}
  .party h3{font-size:9pt;text-transform:uppercase;letter-spacing:.06em;color:#64748b;margin-bottom:8px}
  table.items{width:100%;border-collapse:collapse;margin:24px 0}
  table.items thead th{background:#059669;color:white;padding:10px 14px;text-align:left;font-size:12px}
  table.items tbody td{padding:10px 14px;border-bottom:1px solid #f0fdf4;font-size:12px;vertical-align:top}
  .totals{display:flex;justify-content:flex-end;margin-top:8px}
  .totals-box{width:280px}
  .totals-row{display:flex;justify-content:space-between;padding:6px 0;font-size:12px;border-bottom:1px solid #e2e8f0}
  .totals-row.total{font-weight:700;font-size:14px;border-bottom:none;border-top:2px solid #059669;margin-top:4px;padding-top:10px;color:#059669}
  .payment{margin:24px 0;padding:16px;background:#f8fafc;border-radius:8px;font-size:11px}
  .payment h3{font-size:10pt;margin-bottom:8px;color:#059669}
  .footer{margin-top:40px;padding-top:12px;border-top:1px solid #e2e8f0;font-size:8.5pt;color:#94a3b8;text-align:center}
  .print-btn{position:fixed;top:16px;right:16px;background:#059669;color:white;border:none;padding:9px 20px;border-radius:8px;cursor:pointer;font-size:14px;font-family:inherit}
  @media print{.print-btn{display:none}.page{padding:20px}}
</style>
</head>
<body>
<button class="print-btn" onclick="window.print()">🖨️ Imprimir / PDF</button>
<div class="page">
  <div class="header">
    <div>
      <div class="co-name">${empresa.nombre}</div>
      <div class="co-info">NIF: ${empresa.nif} · ${empresa.direccion}, ${empresa.ciudad}<br>${empresa.email} · ${empresa.telefono}</div>
    </div>
    <div class="doc-title">
      <h1>FACTURA</h1>
      <p>Nº ${numFactura}</p>
      <p>Fecha: ${fechaHoy}</p>
    </div>
  </div>

  <div class="parties">
    <div class="party">
      <h3>Emisor</h3>
      <p><strong>${empresa.nombre}</strong><br>NIF: ${empresa.nif}<br>${empresa.direccion}, ${empresa.ciudad}</p>
    </div>
    <div class="party">
      <h3>Cliente / Receptor</h3>
      <p><strong>${formData['Nombre del Cliente']}</strong><br>NIF/CIF: ${formData['NIF o CIF del Cliente']}<br>Email: ${formData['Email del Cliente']}</p>
    </div>
  </div>

  <table class="items">
    <thead><tr>
      <th style="width:60px;text-align:center">Cant.</th>
      <th>Descripción</th>
      <th style="width:120px;text-align:right">Precio Unit.</th>
      <th style="width:120px;text-align:right">Total</th>
    </tr></thead>
    <tbody>${lineRows}</tbody>
  </table>

  <div class="totals">
    <div class="totals-box">
      <div class="totals-row"><span>Base imponible</span><span>${fmt(base)}</span></div>
      <div class="totals-row"><span>IVA (${iva}%)</span><span>${fmt(ivaAmount)}</span></div>
      <div class="totals-row total"><span>TOTAL</span><span>${fmt(total)}</span></div>
    </div>
  </div>

  <div class="payment">
    <h3>Datos de Pago</h3>
    <p>Cuenta bancaria: <strong>${empresa.banco}</strong><br>
    Concepto: ${numFactura} – ${formData['Nombre del Cliente']}</p>
  </div>

  <div class="footer">Esta factura ha sido emitida de conformidad con la normativa fiscal española · ${numFactura}</div>
</div>
</body>
</html>`;

return [{json: {html, numFactura, clienteNombre: formData['Nombre del Cliente'], base: base.toFixed(2), iva, total: total.toFixed(2), fecha: new Date().toISOString().split('T')[0]}}];
